import { describe, expect, it, vi, beforeEach, afterEach } from 'vitest';
import { supabaseAdmin } from '../supabase.js';
import * as repoModule from '../repo.js';
import type { ChangeLogEntry } from '@asohav/shared';

// Mock the supabase module entirely so every Supabase insert() call goes through spies.
const selectSpy = vi.fn().mockReturnValue({ then: () => ({ data: null, error: null }) });
const upsertSpy = vi.fn();

vi.mock('../supabase.js', () => ({
  supabaseAdmin: {
    from: vi.fn(() => ({
      select: selectSpy,
      upsert: upsertSpy,
      insert: vi.fn().mockResolvedValue({ error: null }),
      update: vi.fn().mockResolvedValue({ error: null }),
      delete: vi.fn().mockResolvedValue({ error: null }),
      eq: vi.fn().mockReturnThis(),
      order: vi.fn().mockReturnThis(),
      limit: vi.fn().mockReturnThis(),
      maybeSingle: vi.fn().mockReturnThis(),
      in: vi.fn().mockReturnThis(),
      ilike: vi.fn().mockReturnThis(),
    })),
    auth: {
      admin: {
        listUsers: vi.fn().mockResolvedValue({ data: { users: [] }, error: null }),
        updateUserById: vi.fn().mockResolvedValue({ error: null }),
        generateLink: vi.fn().mockResolvedValue({ data: { properties: {} }, error: null }),
        getUserById: vi.fn().mockResolvedValue({ data: { user: null }, error: null }),
      },
    },
  },
}));

// Import repo *after* the mock so its module-level binding picks up the spy.
// We need the fresh insert spy that was created inside `supabaseAdmin.from`.

function getInsertSpy() {
  const fromMock = vi.mocked(supabaseAdmin.from);
  const firstCall = fromMock.mock.results?.[0] || { value: undefined };
  // The `.from('changelog')` call returns an object whose `.insert` is the spy we need.
  // We track the actual spy by wrapping the mock in the test setup below.
  return insertSpy;
}

// We'll override the from() mock per test to control each insert result.
let changelogInsertMock: any;

beforeEach(() => {
  vi.resetAllMocks();
  changelogInsertMock = vi.fn().mockResolvedValue({ error: null });

  // Replace the from() mock with one that returns our controlled spy for 'changelog'.
  vi.mocked(supabaseAdmin.from).mockImplementation((table: string) => {
    if (table === 'changelog') {
      return {
        select: vi.fn().mockReturnThis(),
        insert: changelogInsertMock,
        update: vi.fn().mockReturnThis(),
        delete: vi.fn().mockReturnThis(),
        eq: vi.fn().mockReturnThis(),
        order: vi.fn().mockReturnThis(),
        limit: vi.fn().mockReturnThis(),
        maybeSingle: vi.fn().mockReturnThis(),
        upsert: vi.fn().mockReturnThis(),
        in: vi.fn().mockReturnThis(),
        ilike: vi.fn().mockReturnThis(),
      };
    }
    // For any non-changelog table, return a harmless passthrough.
    return {
